'use client';

import { useState } from 'react';

import {
  CheckIcon,
  ClockIcon,
  DownloadIcon,
  BriefcaseIcon,
} from '@/registry/ndeko/lib/icons';
import { Chip } from '@/registry/ndeko/ui/chip';

import {
  ActionButton,
  useTimedAction,
  type ActionLabels,
} from './_parts/action-button';
import {
  ModalDescription,
  ModalFooter,
  ModalHeader,
  ModalPreview,
  ModalTitle,
} from './_parts/modal-frame';
import { Swap } from './_parts/swap';

type TimeEntry = { id: string; task: string; date: string; minutes: number };

const ENTRIES: TimeEntry[] = [
  {
    id: 'entry-1',
    task: 'Design system audit',
    date: 'Mon 5 Oct',
    minutes: 270,
  },
  {
    id: 'entry-2',
    task: 'Onboarding screens',
    date: 'Wed 7 Oct',
    minutes: 90,
  },
  {
    id: 'entry-3',
    task: 'Review with the client',
    date: 'Fri 9 Oct',
    minutes: 120,
  },
];

const HOURLY_RATE = 62;

const FEE_PERCENT = 10;

const MINUTES_PER_HOUR = 60;

const CLIENT_GEM = { '--gem': 'var(--info)' } as React.CSSProperties;

const MONEY = new Intl.NumberFormat('en-US', {
  style: 'currency',
  currency: 'USD',
});

const EXPORT_LABELS: ActionLabels = {
  idle: 'Export invoice',
  working: 'Exporting',
  done: 'Exported',
};

function durationOf(minutes: number) {
  const hours = Math.floor(minutes / MINUTES_PER_HOUR);
  const rest = minutes % MINUTES_PER_HOUR;
  const paddedRest = String(rest).padStart(2, '0');
  return `${hours}h ${paddedRest}m`;
}

function totalMinutesOf(entries: TimeEntry[]) {
  let total = 0;
  for (const entry of entries) {
    total += entry.minutes;
  }
  return total;
}

function paymentLabelsOf(isPaid: boolean): ActionLabels {
  if (isPaid) {
    return { idle: 'Mark as unpaid', working: 'Saving', done: 'Saved' };
  }
  return { idle: 'Mark as paid', working: 'Saving', done: 'Saved' };
}

function StatusChip({ isPaid }: { isPaid: boolean }) {
  const statusKey = String(isPaid);

  return (
    <Swap swapKey={statusKey}>
      {isPaid && (
        <Chip color='var(--success)'>
          <CheckIcon strokeWidth={2.5} />
          Paid
        </Chip>
      )}
      {!isPaid && (
        <Chip color='var(--warning)'>
          <ClockIcon strokeWidth={2.25} />
          Pending
        </Chip>
      )}
    </Swap>
  );
}

function EntriesTable({ totalMinutes }: { totalMinutes: number }) {
  return (
    <div className='bg-card hairline-ring ring-border overflow-hidden rounded-xl shadow-[0_1px_2px_rgb(0_0_0/0.04)]'>
      <table className='w-full text-[13px]'>
        <caption className='sr-only'>Time entries of the invoice</caption>
        <thead>
          <tr className='hairline-b border-border text-muted-foreground text-xs'>
            <th scope='col' className='px-3 py-2 text-left font-medium'>
              Task
            </th>
            <th scope='col' className='px-3 py-2 text-left font-medium'>
              Date
            </th>
            <th scope='col' className='px-3 py-2 text-right font-medium'>
              Time
            </th>
          </tr>
        </thead>
        <tbody>
          {ENTRIES.map((entry) => (
            <tr key={entry.id} className='hairline-b border-border'>
              <td className='w-full max-w-0 truncate px-3 py-2.5'>
                {entry.task}
              </td>
              <td className='text-muted-foreground px-3 py-2.5 whitespace-nowrap'>
                {entry.date}
              </td>
              <td className='px-3 py-2.5 text-right whitespace-nowrap tabular-nums'>
                {durationOf(entry.minutes)}
              </td>
            </tr>
          ))}
        </tbody>
        <tfoot>
          <tr>
            <th
              scope='row'
              colSpan={2}
              className='px-3 py-2.5 text-left font-medium'
            >
              Total
            </th>
            <td className='px-3 py-2.5 text-right font-medium whitespace-nowrap tabular-nums'>
              {durationOf(totalMinutes)}
            </td>
          </tr>
        </tfoot>
      </table>
    </div>
  );
}

function PaymentRecordContent() {
  const [isPaid, setIsPaid] = useState(false);
  const payment = useTimedAction();
  const exporting = useTimedAction();
  const totalMinutes = totalMinutesOf(ENTRIES);
  const hours = totalMinutes / MINUTES_PER_HOUR;
  const earned = hours * HOURLY_RATE;
  const fee = (earned * FEE_PERCENT) / 100;
  const takeHome = earned - fee;
  const paymentLabels = paymentLabelsOf(isPaid);

  function togglePaid() {
    payment.run(() => {
      setIsPaid((previous) => !previous);
    });
  }

  function exportInvoice() {
    exporting.run(() => {});
  }

  return (
    <>
      <ModalHeader>
        <ModalTitle>Payment record</ModalTitle>
        <ModalDescription>Invoice INV-2026-118 · October 2026</ModalDescription>
      </ModalHeader>
      <dl className='grid grid-cols-2 gap-4'>
        <div className='flex min-w-0 flex-col gap-1'>
          <dt className='text-muted-foreground text-xs'>Client</dt>
          <dd className='flex min-w-0 items-center gap-2 text-[13px] font-medium'>
            <span
              style={CLIENT_GEM}
              className='gem-plate flex size-5 shrink-0 items-center justify-center rounded-[5px]'
            >
              <BriefcaseIcon className='size-3' strokeWidth={2.25} />
            </span>
            <span className='truncate'>Fernwick Studio</span>
          </dd>
        </div>
        <div className='flex min-w-0 flex-col gap-1'>
          <dt className='text-muted-foreground text-xs'>Job</dt>
          <dd className='truncate text-[13px] font-medium'>Product design</dd>
        </div>
      </dl>
      <div className='flex flex-wrap items-center gap-1.5'>
        <StatusChip isPaid={isPaid} />
        <Chip color='var(--info)'>{`Hourly · ${MONEY.format(HOURLY_RATE)}`}</Chip>
      </div>
      <EntriesTable totalMinutes={totalMinutes} />
      <dl className='flex flex-col gap-2 text-[13px]'>
        <div className='flex items-baseline justify-between gap-4'>
          <dt className='text-muted-foreground'>
            {`${hours} h × ${MONEY.format(HOURLY_RATE)}`}
          </dt>
          <dd className='tabular-nums'>{MONEY.format(earned)}</dd>
        </div>
        <div className='flex items-baseline justify-between gap-4'>
          <dt className='text-muted-foreground'>
            {`Platform fee, ${FEE_PERCENT}%`}
          </dt>
          <dd className='tabular-nums'>{`−${MONEY.format(fee)}`}</dd>
        </div>
        <div className='flex items-end justify-between gap-4 pt-2'>
          <dt className='flex flex-col gap-0.5'>
            <span className='font-medium'>Take-home</span>
            <span className='text-muted-foreground text-xs'>
              Illustrative figures
            </span>
          </dt>
          <dd className='text-2xl font-semibold tabular-nums'>
            {MONEY.format(takeHome)}
          </dd>
        </div>
      </dl>
      <ModalFooter>
        <ActionButton
          variant='outline'
          state={payment.state}
          labels={paymentLabels}
          onClick={togglePaid}
        />
        <ActionButton
          state={exporting.state}
          labels={EXPORT_LABELS}
          idleIcon={<DownloadIcon />}
          onClick={exportInvoice}
        />
      </ModalFooter>
    </>
  );
}

export default function Modal14() {
  return (
    <ModalPreview triggerLabel='Open payment record' size='md'>
      <PaymentRecordContent />
    </ModalPreview>
  );
}

'use client';

import { useEffect, useRef, useState } from 'react';

import { CheckIcon, LoaderCircleIcon } from '@/registry/ndeko/lib/icons';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button, type ButtonProps } from '@/registry/ndeko/ui/button';

import { Swap } from './swap';

export type ActionState = 'idle' | 'working' | 'done';

export type ActionLabels = Record<ActionState, string>;

const WORKING_MS = 800;

const DONE_MS = 1600;

/** The life of an action that takes a moment: working, then done for a beat, then ready again. The change is committed when the work ends. */
export function useTimedAction() {
  const [state, setState] = useState<ActionState>('idle');
  const commitRef = useRef<(() => void) | null>(null);

  useEffect(() => {
    if (state === 'working') {
      const timeout = window.setTimeout(() => {
        const commit = commitRef.current;
        commitRef.current = null;
        if (commit) {
          commit();
        }
        setState('done');
      }, WORKING_MS);
      return () => window.clearTimeout(timeout);
    }
    if (state === 'done') {
      const timeout = window.setTimeout(() => {
        setState('idle');
      }, DONE_MS);
      return () => window.clearTimeout(timeout);
    }
  }, [state]);

  function run(commit: () => void) {
    if (state !== 'idle') {
      return;
    }
    commitRef.current = commit;
    setState('working');
  }

  const isBusy = state !== 'idle';

  return { state, run, isBusy };
}

function iconOf(state: ActionState, idleIcon: React.ReactNode) {
  if (state === 'working') {
    return <LoaderCircleIcon className='animate-spin' />;
  }
  if (state === 'done') {
    return <CheckIcon />;
  }
  return idleIcon;
}

type ActionButtonProps = Omit<ButtonProps, 'children'> & {
  state: ActionState;
  labels: ActionLabels;
  idleIcon?: React.ReactNode;
};

/** One button that becomes its next state: its icon swaps, its label crossfades and its width follows the new label. */
export function ActionButton({
  state,
  labels,
  idleIcon,
  ...props
}: ActionButtonProps) {
  const icon = iconOf(state, idleIcon);
  const hasIcon = Boolean(icon);
  const label = labels[state];
  const isWorking = state === 'working';
  const isDone = state === 'done';

  return (
    <>
      <Button aria-busy={isWorking} {...props}>
        {hasIcon && <Swap swapKey={state}>{icon}</Swap>}
        <AnimatedSize axis='width' as='span'>
          <Swap swapKey={label} kind='label'>
            {label}
          </Swap>
        </AnimatedSize>
      </Button>
      <span className='sr-only' role='status'>
        {isDone && labels.done}
      </span>
    </>
  );
}

'use client';

import { createContext, useContext } from 'react';

import { SquareArrowOutUpRightIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button, type ButtonProps } from '@/registry/ndeko/ui/button';
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogTitle,
  DialogTrigger,
} from '@/registry/ndeko/ui/dialog';

/** Where a modal's content is drawn: open in the page as a preview, or inside the real dialog. */
export type ModalHost = 'preview' | 'dialog';

const ModalHostContext = createContext<ModalHost>('preview');

export function useModalHost() {
  return useContext(ModalHostContext);
}

export type ModalSize = 'sm' | 'md' | 'lg' | 'xl';

const SIZE_CLASS: Record<ModalSize, string> = {
  sm: 'max-w-sm',
  md: 'max-w-md',
  lg: 'max-w-lg',
  xl: 'max-w-[44rem]',
};

const TITLE = 'text-lg leading-tight font-semibold text-balance';

const DESCRIPTION = 'text-muted-foreground text-[13px]';

const BODY = 'flex flex-col gap-4';

type ModalTextProps = { className?: string; children: React.ReactNode };

export function ModalTitle({ className, children }: ModalTextProps) {
  const host = useModalHost();
  if (host === 'dialog') {
    return <DialogTitle className={className}>{children}</DialogTitle>;
  }
  return <h2 className={cn(TITLE, className)}>{children}</h2>;
}

export function ModalDescription({ className, children }: ModalTextProps) {
  const host = useModalHost();
  if (host === 'dialog') {
    return (
      <DialogDescription className={className}>{children}</DialogDescription>
    );
  }
  return <p className={cn(DESCRIPTION, className)}>{children}</p>;
}

/** Leaves room for the dialog's close button, so the preview and the dialog lay out the same. */
export function ModalHeader({
  className,
  ...props
}: React.ComponentProps<'div'>) {
  return (
    <div className={cn('flex flex-col gap-1.5 pr-8', className)} {...props} />
  );
}

export function ModalFooter({
  className,
  ...props
}: React.ComponentProps<'div'>) {
  return (
    <div
      className={cn(
        'flex flex-col-reverse gap-2 sm:flex-row sm:items-center sm:justify-end',
        className
      )}
      {...props}
    />
  );
}

/** Closes the dialog. In the preview it stays a plain button that runs its own action, if any. */
export function ModalCloseButton({ children, ...props }: ButtonProps) {
  const host = useModalHost();
  if (host === 'dialog') {
    return <DialogClose render={<Button {...props} />}>{children}</DialogClose>;
  }
  return <Button {...props}>{children}</Button>;
}

type ModalPreviewProps = {
  /** The content, drawn twice: open in the page, and inside the dialog the trigger opens. */
  children: React.ReactNode;
  triggerLabel: string;
  size?: ModalSize;
  className?: string;
};

/** Shows a modal open and whole on the page, with a small trigger that opens the same content in the real dialog. */
export function ModalPreview({
  children,
  triggerLabel,
  size = 'md',
  className,
}: ModalPreviewProps) {
  const sizeClass = SIZE_CLASS[size];

  return (
    <div className='flex w-full flex-col items-center gap-4'>
      <ModalHostContext.Provider value='preview'>
        <div
          className={cn(
            'surface-raised w-full rounded-2xl p-6 text-left',
            sizeClass,
            className
          )}
        >
          <AnimatedSize contentClassName={BODY}>{children}</AnimatedSize>
        </div>
      </ModalHostContext.Provider>
      <Dialog>
        <DialogTrigger render={<Button variant='outline' size='sm' />}>
          <SquareArrowOutUpRightIcon />
          {triggerLabel}
        </DialogTrigger>
        <DialogContent className={cn(sizeClass, className)}>
          <ModalHostContext.Provider value='dialog'>
            {children}
          </ModalHostContext.Provider>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import type { Transition, Variants } from 'motion/react';

export const SWAP_TRANSITION: Transition = {
  duration: 0.15,
  ease: [0.2, 0, 0, 1],
};

const MORPH_SPRING: Transition = { type: 'spring', bounce: 0, duration: 0.3 };

const INSTANT: Transition = { duration: 0 };

const PRESENCE_IN: Transition = { duration: 0.2, ease: [0.23, 1, 0.32, 1] };

const PRESENCE_OUT: Transition = { duration: 0.14, ease: [0.23, 1, 0.32, 1] };

const ICON_SWAP: Variants = {
  enter: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  visible: { opacity: 1, scale: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
};

const LABEL_SWAP: Variants = {
  enter: { opacity: 0, filter: 'blur(2px)' },
  visible: { opacity: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, filter: 'blur(2px)' },
};

const FADE_SWAP: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0 },
};

const ROW_PRESENCE: Variants = {
  hidden: {
    height: 0,
    opacity: 0,
    overflow: 'hidden',
    transition: PRESENCE_OUT,
  },
  shown: {
    height: 'auto',
    opacity: 1,
    transition: PRESENCE_IN,
    transitionEnd: { overflow: 'visible' },
  },
};

const ROW_FADE: Variants = {
  hidden: { opacity: 0, transition: PRESENCE_OUT },
  shown: { opacity: 1, transition: PRESENCE_IN },
};

const CHIP_PRESENCE: Variants = {
  hidden: { opacity: 0, scale: 0.9, transition: PRESENCE_OUT },
  shown: { opacity: 1, scale: 1, transition: PRESENCE_IN },
};

export type SwapKind = 'icon' | 'label';

export function swapVariantsOf(
  shouldReduceMotion: boolean | null,
  kind: SwapKind = 'icon'
) {
  if (shouldReduceMotion) {
    return FADE_SWAP;
  }
  if (kind === 'label') {
    return LABEL_SWAP;
  }
  return ICON_SWAP;
}

/** A row added to or removed from a list: its height opens or collapses, so the rows after it slide. */
export function rowVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return ROW_FADE;
  }
  return ROW_PRESENCE;
}

export function chipVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return ROW_FADE;
  }
  return CHIP_PRESENCE;
}

export function morphOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  return MORPH_SPRING;
}

'use client';

import { AnimatePresence, motion, useReducedMotion } from 'motion/react';

import { cn } from '@/registry/ndeko/lib/utils';

import { SWAP_TRANSITION, swapVariantsOf, type SwapKind } from './motion';

type SwapProps = {
  /** Changes when the content becomes another: the old one leaves while the new one arrives in its place. */
  swapKey: string;
  kind?: SwapKind;
  className?: string;
  /** Classes of the moving content, for example `min-w-0 max-w-full` so a long text can truncate inside. */
  contentClassName?: string;
  children: React.ReactNode;
};

export function Swap({
  swapKey,
  kind = 'icon',
  className,
  contentClassName,
  children,
}: SwapProps) {
  const shouldReduceMotion = useReducedMotion();
  const variants = swapVariantsOf(shouldReduceMotion, kind);

  return (
    <span className={cn('relative inline-flex items-center', className)}>
      <AnimatePresence mode='popLayout' initial={false}>
        <motion.span
          key={swapKey}
          className={cn(
            'inline-flex items-center gap-[inherit] whitespace-nowrap',
            contentClassName
          )}
          variants={variants}
          initial='enter'
          animate='visible'
          exit='exit'
          transition={SWAP_TRANSITION}
        >
          {children}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}
